package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strconv"
	"strings"

	"google.golang.org/protobuf/types/known/structpb"
	"google.golang.org/protobuf/types/known/timestamppb"

	commonv1 "github.com/mellifera/mellifera/proto/mellifera/common/v1"
	metadatav1 "github.com/mellifera/mellifera/proto/mellifera/metadata/v1"
)

// errNoCandidates marks an empty (but valid) upstream result list — a soft
// error the core records without corrupting the document.
var errNoCandidates = errors.New("tmdb returned no candidates")

// Candidate-selection keys and the convention kind values this plugin's
// namespace writes. kindKey is the query key the preference score reads;
// kindMovie/kindTV the two kind values a tmdb entry can carry.
const (
	kindKey   = "kind"
	kindMovie = "movie"
	kindTV    = "tv"

	// resolvedIDsKey rides inside Convert's metadata so the core can lift it
	// into doc.identifiers; Merge strips it — it is NEVER a namespace field.
	resolvedIDsKey = "resolved_ids"
)

// Asset hosts. TMDB serves artwork and public pages from hosts SEPARATE from
// the API base the fetch templates bake (source.go), so the namespace's
// absolute URL compositions are their own constants — the shikimori
// absoluteURL precedent applied plugin-side (poster_path and profile_path are
// always relative paths; the public page is derived from the id + kind).
const (
	// imageBase composes the relative artwork paths tmdb serves
	// (poster_path: "/abc.jpg") into an absolute image.tmdb.org URL.
	imageBase = "https://image.tmdb.org/t/p/original"

	// siteBase composes the public page URL (the namespace url field):
	// /movie/{id} or /tv/{id}.
	siteBase = "https://www.themoviedb.org"
)

// Convert normalizes the raw tmdb payload into the RU-first sources.tmdb
// namespace: title{russian, romaji: original_title}, description, genres,
// score, kind, status, episodes, aired_on, poster, url. BuildRequest pins
// language=ru-RU, so the served title/overview/genre names ARE the russian
// strings; the original title rides the romaji slot. The payload is either
// the search envelope {"results":[…]} — it runs the preference score and
// picks ONE candidate — or a single detail object (the anchored fetch). The
// resolved tmdb_id rides inside the metadata under resolved_ids (the core
// lifts it into doc.identifiers; Merge strips it — never a namespace field).
// Provenance carries hints only (plugin_version + source_url); the core
// stamps _provenance authoritatively. Honest absence everywhere: a field the
// payload does not serve is ABSENT from the namespace — never an empty
// string, zero, or placeholder. A non-run (empty result list, unparsable
// body) sets Error and leaves metadata empty; Convert never errors the chain.
func (*sourceImpl) Convert(_ context.Context, req *metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
	entry, err := decodeEntry(req.GetRawResponse(), req.GetQuery())
	if err != nil {
		return &metadatav1.ConvertResult{
			Error: &metadatav1.Error{Code: errorCode(err), Message: err.Error()},
		}, nil
	}
	m := namespaceFields(entry)
	m[resolvedIDsKey] = map[string]any{idKey: entry.ID}
	// The anchored plans' ONE extra is position-shared and SHAPE-keyed:
	// extras[0] is credits on the film plan (source.go's creditsSpec — the
	// cast source) and season on the series plan (seasonSpec — the
	// episode-titles source). Each converter decodes only its own payload
	// shape, so a season body composes no cast and a credits body composes no
	// entries. An extra that never arrived (soft-failed) or carries no usable
	// payload leaves both contributions absent — honest absence. Search plans
	// declare no extras, so an unanchored run stays single-fetch with no
	// contributions at all. The episode titles ride OUTSIDE the namespace —
	// they are ConvertResult.EpisodeTitles (the core's episode-document
	// routing input), never a namespace field.
	var episodeTitles []*metadatav1.EpisodeTitle
	if extras := req.GetExtraResponses(); len(extras) > 0 && extras[0].GetFetched() {
		body := extras[0].GetBody()
		if cast := castFromCredits(body); len(cast) > 0 {
			m[castKey] = cast
		}
		episodeTitles = episodeTitlesFromSeason(body)
	}
	sourceURL, _ := m["url"].(string)
	meta := toStruct(m)
	return &metadatav1.ConvertResult{
		Metadata:      meta,
		Provenance:    provenanceHints(meta, sourceURL),
		EpisodeTitles: episodeTitles,
	}, nil
}

// tmdbEntry mirrors the tmdb payload object (v3 API): movies carry
// title/original_title/release_date, tv carries name/original_name/
// first_air_date — one struct decodes both shapes, and isTV reads the
// tv-shaped name field (no media_type field the payload always serves).
// vote_average is a decimal NUMBER upstream; json.Number accepts it as
// either a bare number or the string form. Search results carry genre_ids
// (numeric) instead of the localized genres array and neither status nor
// number_of_episodes; the namespace writes those only where the payload
// actually served them (honest absence).
type tmdbEntry struct {
	ID               int64       `json:"id"`
	Title            string      `json:"title"`
	Name             string      `json:"name"`
	OriginalTitle    string      `json:"original_title"`
	OriginalName     string      `json:"original_name"`
	Overview         string      `json:"overview"`
	Genres           []tmdbGenre `json:"genres"`
	VoteAverage      json.Number `json:"vote_average"`
	Status           string      `json:"status"`
	NumberOfEpisodes int64       `json:"number_of_episodes"`
	ReleaseDate      string      `json:"release_date"`
	FirstAirDate     string      `json:"first_air_date"`
	PosterPath       string      `json:"poster_path"`
}

// tmdbGenre mirrors one entry of the detail payload's genres array (the
// localized name — language=ru-RU serves them russian-first).
type tmdbGenre struct {
	Name string `json:"name"`
}

// isTV reports the tv-shaped entry: the localized field for tv is name
// (movies carry title), so the shape itself distinguishes the kinds.
func (e tmdbEntry) isTV() bool {
	return e.Name != ""
}

// kind reports the convention kind value for the entry.
func (e tmdbEntry) kind() string {
	if e.isTV() {
		return kindTV
	}
	return kindMovie
}

// localizedTitle is the entry's title in the served language (russian under
// the pinned ru-RU): name for tv, title for movies.
func (e tmdbEntry) localizedTitle() string {
	if e.isTV() {
		return e.Name
	}
	return e.Title
}

// originalTitle is the entry's original-language title: original_name for tv,
// original_title for movies — the romaji slot of the convention title object.
func (e tmdbEntry) originalTitle() string {
	if e.isTV() {
		return e.OriginalName
	}
	return e.OriginalTitle
}

// entryDate is the entry's air date: first_air_date for tv, release_date for
// movies.
func (e tmdbEntry) entryDate() string {
	if e.isTV() {
		return e.FirstAirDate
	}
	return e.ReleaseDate
}

// decodeEntry parses the raw response body: the search envelope
// {"results":[…]} runs selectCandidate over the query, a single detail
// object is the anchored fetch answer, anything else is a parse error.
func decodeEntry(body []byte, query *structpb.Struct) (tmdbEntry, error) {
	var page struct {
		Results []tmdbEntry `json:"results"`
	}
	if err := json.Unmarshal(body, &page); err == nil && page.Results != nil {
		if len(page.Results) == 0 {
			return tmdbEntry{}, errNoCandidates
		}
		return selectCandidate(page.Results, query), nil
	}
	var single tmdbEntry
	if err := json.Unmarshal(body, &single); err != nil {
		return tmdbEntry{}, fmt.Errorf("tmdb response is neither a search list nor a detail object: %w", err)
	}
	return single, nil
}

// errorCode maps decodeEntry failures onto the Convert error vocabulary.
func errorCode(err error) string {
	if errors.Is(err, errNoCandidates) {
		return "upstream_empty"
	}
	return "parse_error"
}

// selectCandidate picks the best candidate deterministically: the preference
// score (below), ties broken by upstream order (strictly-greater keeps the
// first). A candidate agreeing on nothing still scores 0 and stays selectable
// — the selection is non-erroring when no signal agrees (it degrades, never
// errors).
func selectCandidate(list []tmdbEntry, query *structpb.Struct) tmdbEntry {
	best := list[0]
	bestScore := candidateScore(best, query)
	for _, cand := range list[1:] {
		if s := candidateScore(cand, query); s > bestScore {
			best, bestScore = cand, s
		}
	}
	return best
}

// candidateScore prefers year + movie/tv kind agreement (each worth 2).
// Absent query facts score nothing; no fact ever penalizes.
func candidateScore(c tmdbEntry, query *structpb.Struct) int {
	f := query.GetFields()
	score := 0
	if q := int64(f[yearKey].GetNumberValue()); q > 0 && dateYear(c.entryDate()) == q {
		score += 2
	}
	if q := f[kindKey].GetStringValue(); q != "" && q == c.kind() {
		score += 2
	}
	return score
}

// dateYear reads the "YYYY" prefix of a tmdb date ("1999-10-15"); an
// unparsable or empty date yields 0 and never matches a query year.
func dateYear(date string) int64 {
	if len(date) < 4 {
		return 0
	}
	y, err := strconv.ParseInt(date[:4], 10, 64)
	if err != nil {
		return 0
	}
	return y
}

// namespaceFields builds the sources.tmdb namespace map (RU-first). Every
// field is written only where the payload actually serves it (honest
// absence): a missing overview, genres, poster, date, status, or score is
// absent — never an empty string, zero, empty array, or placeholder. kind is
// the one always-present field: the plugin derives it from the payload
// shape, not from an upstream field that can be missing.
func namespaceFields(e tmdbEntry) map[string]any {
	m := map[string]any{}
	title := map[string]any{}
	if localized := e.localizedTitle(); localized != "" {
		title["russian"] = localized
	}
	if original := e.originalTitle(); original != "" {
		title["romaji"] = original
	}
	if len(title) > 0 {
		m["title"] = title
	}
	if e.Overview != "" {
		m["description"] = e.Overview
	}
	if names := genreNames(e.Genres); len(names) > 0 {
		m["genres"] = names
	}
	if s, err := e.VoteAverage.Float64(); err == nil && s > 0 {
		m["score"] = s
	}
	m["kind"] = e.kind()
	if e.Status != "" {
		m["status"] = e.Status
	}
	if e.NumberOfEpisodes > 0 {
		m["episodes"] = e.NumberOfEpisodes
	}
	if aired := e.entryDate(); aired != "" {
		m["aired_on"] = aired
	}
	if poster := absoluteImageURL(e.PosterPath); poster != "" {
		m["poster"] = poster
	}
	if e.ID > 0 {
		m["url"] = siteURL(e)
	}
	return m
}

// genreNames renders the localized genre names (language=ru-RU serves them
// russian-first). A genre with no usable name is skipped; a payload without
// the genres array (the search results' numeric genre_ids carry no names)
// composes nothing — the field stays absent rather than empty.
func genreNames(genres []tmdbGenre) []any {
	out := make([]any, 0, len(genres))
	for _, g := range genres {
		if g.Name != "" {
			out = append(out, g.Name)
		}
	}
	return out
}

// absoluteImageURL composes the relative artwork paths tmdb serves
// (poster_path, profile_path: "/abc.jpg") into absolute image.tmdb.org URLs;
// an already-absolute URL passes through and an empty path stays absent.
func absoluteImageURL(path string) string {
	if path == "" || strings.HasPrefix(path, "http://") || strings.HasPrefix(path, "https://") {
		return path
	}
	return imageBase + path
}

// siteURL composes the public page URL for the entry: /movie/{id} or
// /tv/{id} under the site host — derived from the id + kind, never from an
// upstream field that can be missing.
func siteURL(e tmdbEntry) string {
	if e.isTV() {
		return fmt.Sprintf("%s/tv/%d", siteBase, e.ID)
	}
	return fmt.Sprintf("%s/movie/%d", siteBase, e.ID)
}

// --- Cast: the credits extra payload (the convention cast field) ---

// castKey is the media-data convention's cast field: an array of entries
// each carrying name (the actor), role (the character), and photo_url (the
// portrait composed absolute).
const castKey = "cast"

// tmdbCredits mirrors the /movie/{id}/credits payload: its cast array is
// the convention cast's source; the crew array is ignored.
type tmdbCredits struct {
	Cast []tmdbCastMember `json:"cast"`
}

// tmdbCastMember mirrors one credits cast entry: name the actor, character
// the role they play, profile_path the relative portrait path.
type tmdbCastMember struct {
	Name        string `json:"name"`
	Character   string `json:"character"`
	ProfilePath string `json:"profile_path"`
}

// castFromCredits composes the media-data convention cast array from the
// credits payload: one entry per cast member — name the actor, role the
// character, photo_url the profile path composed absolute (image.tmdb.org
// serves profiles from the same host as the poster). An entry with no actor
// name is skipped; role and photo_url stay absent from an entry whose
// payload serves none. A body that is not a credits object, or one with no
// usable entries, composes nothing (nil) so the cast field stays ABSENT
// rather than empty.
func castFromCredits(body []byte) []any {
	var credits tmdbCredits
	if err := json.Unmarshal(body, &credits); err != nil {
		return nil
	}
	out := make([]any, 0, len(credits.Cast))
	for _, c := range credits.Cast {
		if c.Name == "" {
			continue
		}
		entry := map[string]any{"name": c.Name}
		if c.Character != "" {
			entry["role"] = c.Character
		}
		if photo := absoluteImageURL(c.ProfilePath); photo != "" {
			entry["photo_url"] = photo
		}
		out = append(out, entry)
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

// --- Episode titles: the season extra payload (the convention episode fields) ---

// tmdbSeason mirrors the /tv/{id}/season/{n} payload: its episodes array is
// the episode-titles source. The season object's own name/overview fields are
// the SERIES namespace's concern — the primary tv-detail fetch already serves
// them — and are not decoded here.
type tmdbSeason struct {
	Episodes []tmdbEpisode `json:"episodes"`
}

// tmdbEpisode mirrors one season-episodes entry: episode_number the episode's
// number within the season (the key the core routes entries onto episode
// documents by), name the episode title, overview its description —
// language=ru-RU serves both russian-first.
type tmdbEpisode struct {
	EpisodeNumber int64  `json:"episode_number"`
	Name          string `json:"name"`
	Overview      string `json:"overview"`
}

// episodeTitlesFromSeason converts the season payload into the per-episode
// EpisodeTitle contributions: one entry per usable payload entry — episode
// the served episode_number, metadata the convention episode fields {"title":
// name, "description": overview} — description honestly absent when the
// payload serves no overview. An entry with no usable name is skipped; an
// unparsable body, or one with no usable entries, decodes to nil — the
// contributions stay ABSENT rather than empty, the payload's own order
// preserved. A credits body (the film plan's same-position extra) carries no
// episodes array and composes nothing, so the plan discrimination stays
// shape-keyed.
func episodeTitlesFromSeason(body []byte) []*metadatav1.EpisodeTitle {
	var season tmdbSeason
	if err := json.Unmarshal(body, &season); err != nil {
		return nil
	}
	out := make([]*metadatav1.EpisodeTitle, 0, len(season.Episodes))
	for _, e := range season.Episodes {
		if e.Name == "" {
			continue
		}
		meta := map[string]any{"title": e.Name}
		if e.Overview != "" {
			meta["description"] = e.Overview
		}
		out = append(out, &metadatav1.EpisodeTitle{
			Episode:  e.EpisodeNumber,
			Metadata: toStruct(meta),
		})
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

// provenanceHints builds the per-field provenance hint map the core merges over
// its authoritative _provenance stamp. Each field names tmdb + its version
// + the fetch time + the upstream source_url (audit); the core stamps
// confidence from the Match confidence.
func provenanceHints(meta *structpb.Struct, sourceURL string) map[string]*commonv1.Provenance {
	fields := meta.GetFields()
	out := make(map[string]*commonv1.Provenance, len(fields))
	fetched := timestamppb.Now()
	for field := range fields {
		out[field] = &commonv1.Provenance{
			PluginId:      pluginID,
			PluginVersion: pluginVersion,
			FetchedAt:     fetched,
			SourceUrl:     sourceURL,
		}
	}
	return out
}
